const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { assertContinuousLedger } = require('./enterprise-round2-production-lot.cjs');

// This is deliberately a write-path browser proof, not a DOM-only smoke
// check.  It uses a fresh idempotency key generated by the production UI and
// then reads the resulting immutable voucher through both running instances.
async function productionDispositionBrowser(ctx, fixture, signal) {
  const { expect } = require('playwright/test');
  const { launchBrowserWithGuard } = require('./browser-launch-guard.cjs');
  const { verifyRenderedCjk } = require('./browser-cjk-font-guard.cjs');
  const { workOrder, outputBatch, outputStock } = fixture;
  const evidence = {
    scope: 'Warehouse browser posts one additional physical scrap from a completed output batch and verifies stock, cost, audit, CJK rendering, and two-instance readback.',
    errors: [],
  };
  const call = async (url, method = 'GET', data, actor = ctx.actors.stock0, instance = 0) =>
    ctx.dataOf(await ctx.request(url, { method, data, actor, instance, signal }));
  const snapshot = async () => ({
    batch: await ctx.prisma.productBatch.findUniqueOrThrow({ where: { id: outputBatch.id } }),
    stock: await ctx.prisma.stockBalance.findUniqueOrThrow({ where: { id: outputStock.id } }),
    costs: await ctx.prisma.inventoryCostLedger.findMany({ where: { batchId: outputBatch.id }, orderBy: { id: 'asc' } }),
    dispositions: await ctx.prisma.productionDisposition.findMany({ where: { workOrderId: workOrder.id }, orderBy: { id: 'asc' } }),
    audits: await ctx.prisma.auditLog.findMany({ where: { resource: 'production_disposition' }, orderBy: { id: 'asc' } }),
    entries: await ctx.prisma.stockEntry.findMany({ where: { sourceType: 'production_scrap' }, orderBy: { id: 'asc' } }),
  });
  const launched = await launchBrowserWithGuard({ launchTimeoutMs: 15_000, totalTimeoutMs: 30_000, maxAttemptsPerStrategy: 1 });
  const browser = launched.browser;
  const abort = () => { void browser.close().catch(() => {}); };
  signal.addEventListener('abort', abort, { once: true });
  const directory = path.join(path.dirname(ctx.reportPath), `${ctx.runId}-production-disposition`);
  fs.mkdirSync(directory, { recursive: true });
  try {
    evidence.before = await snapshot();
    assert.equal(Number(evidence.before.batch.stockQuantity), 7);
    assert.equal(Number(evidence.before.stock.quantity), 7);
    assert.equal(evidence.before.dispositions.length, 2);

    const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
    page.setDefaultTimeout(15_000);
    page.on('pageerror', error => evidence.errors.push(error.message));
    page.on('response', response => {
      if (response.status() >= 400 && response.url().includes('/api/')) {
        evidence.errors.push(`${response.status()} ${new URL(response.url()).pathname}`);
      }
    });
    const actor = ctx.actors.stock0;
    await page.addInitScript(({ token, user }) => {
      for (const key of ['token', 'auth_token', 'erp_auth_token']) localStorage.setItem(key, token);
      for (const key of ['user', 'currentUser', 'erp_current_user']) localStorage.setItem(key, JSON.stringify(user));
      localStorage.setItem('ailao.language', 'zh');
      localStorage.setItem('language', 'zh-CN');
    }, { token: actor.token, user: { id: String(actor.id), name: actor.job, role: actor.role, segment: 'mixed' } });

    await page.goto(`${ctx.urls[1]}/#production`);
    await page.locator('#loading').waitFor({ state: 'hidden' });
    await page.getByTestId('production-desk-batches').click();
    await page.getByTestId('production-batch-search-input').fill(outputBatch.batchNo);
    await page.getByTestId(`production-batch-row-${outputBatch.id}`).click();
    const panel = page.getByTestId('production-disposition-panel');
    await expect(panel).toContainText(workOrder.workOrderNo);
    await page.getByTestId('production-disposition-template-production_loss').click();
    await expect(page.getByTestId('production-disposition-stock-balance')).toHaveValue(String(outputStock.id));
    await page.getByTestId('production-adjustment-quantity-input').fill('1');
    await page.getByTestId('production-adjustment-reason-input').fill('Browser verified physical scrap');
    await page.getByTestId('production-adjustment-note-input').fill(`Round2 browser proof ${ctx.runId}`);
    evidence.font = await verifyRenderedCjk(page, '[data-testid="production-disposition-panel"]');
    evidence.screenshot = path.join(directory, 'physical-scrap-before-post.png');
    await panel.screenshot({ path: evidence.screenshot, animations: 'disabled' });
    const post = page.waitForResponse(response => (
      response.request().method() === 'POST'
      && new URL(response.url()).pathname === `/api/production/work-orders/${workOrder.id}/dispositions`
    ));
    await page.getByTestId('production-adjustment-save').click();
    const posted = await post;
    assert.equal(posted.status(), 201);
    evidence.disposition = (await posted.json()).data;
    await expect(page.getByText(evidence.disposition.dispositionNo)).toBeVisible();

    evidence.after = await snapshot();
    assert.equal(Number(evidence.after.batch.stockQuantity), 6);
    assert.equal(Number(evidence.after.stock.quantity), 6);
    assertContinuousLedger(evidence.after.costs, 6, 60);
    assert.equal(evidence.after.dispositions.length, 3);
    assert.equal(evidence.after.dispositions.filter(row => row.dispositionType === 'scrap').length, 2);
    assert.equal(evidence.after.dispositions.filter(row => row.id === evidence.disposition.id).length, 1);
    assert.equal(evidence.after.entries.filter(row => row.sourceRef === evidence.disposition.dispositionNo).length, 1);
    assert.equal(evidence.after.audits.filter(row => row.action === 'POST_PRODUCTION_SCRAP_DISPOSITION' && row.resourceId === evidence.disposition.id).length, 1);
    evidence.readbacks = await Promise.all([0, 1].map(async instance => ({
      dispositions: await call(`/production/work-orders/${workOrder.id}/dispositions`, 'GET', undefined, actor, instance),
      stocks: await call(`/warehouses/stock-balances?batchNo=${encodeURIComponent(outputBatch.batchNo)}&pageSize=100`, 'GET', undefined, actor, instance),
    })));
    for (const readback of evidence.readbacks) {
      assert.equal(readback.dispositions.filter(row => row.id === evidence.disposition.id).length, 1);
      assert.equal(Number(readback.stocks.find(row => row.id === outputStock.id)?.quantity), 6);
    }
    assert.deepEqual(evidence.readbacks[0], evidence.readbacks[1]);
    assert.deepEqual(evidence.errors, []);
    return evidence;
  } catch (error) {
    error.evidence ||= evidence;
    throw error;
  } finally {
    signal.removeEventListener('abort', abort);
    await browser.close();
  }
}

module.exports = { productionDispositionBrowser };
